\set ON_ERROR_STOP on
set role authenticated;
set request.jwt.claim.sub='00000000-0000-0000-0000-000000000001';
insert into test.ids values('patient',public.fh_create_demo_patient());
select test.ok((select count(*)=1 from public.fh_patients),'administrator can see owned patient');
select test.denied($$insert into public.fh_memberships values((select id from test.ids where name='patient'),'00000000-0000-0000-0000-000000000004','administrator',now())$$,'direct membership insertion');
select test.denied($$update public.fh_memberships set role='family_member'$$,'direct role changes');
select test.denied($$delete from public.fh_memberships$$,'direct membership deletion');
select test.denied($$delete from public.fh_patients$$,'patient deletion cannot bypass last administrator');
select test.denied($$select fh_private.log_event((select id from test.ids where name='patient'),'forged')$$,'private definer helper');
select test.denied($$insert into public.fh_audit_events(patient_id,event) values((select id from test.ids where name='patient'),'forged')$$,'audit forgery');
insert into public.fh_doctors(patient_id,name,specialty) values((select id from test.ids where name='patient'),'Fictional doctor','Demo') returning id as doctor_id \gset
insert into test.ids values('doctor',:'doctor_id');
insert into public.fh_medications(patient_id,doctor_id,name) values((select id from test.ids where name='patient'),:'doctor_id','Fictional medication');
insert into public.fh_appointments(patient_id,doctor_id,reason,starts_at) values((select id from test.ids where name='patient'),:'doctor_id','Fictional future visit',now()+interval '30 days') returning id as appointment_id \gset
insert into test.ids values('appointment',:'appointment_id');
insert into public.fh_appointments(patient_id,reason,starts_at) values((select id from test.ids where name='patient'),'Fictional past visit',now()-interval '1 day') returning id as past_id \gset
insert into test.ids values('past',:'past_id');
insert into public.fh_medical_history(patient_id,summary,occurred_on) values((select id from test.ids where name='patient'),'Fictional note',current_date);
update public.fh_medications set status='Confirmed';
select test.ok((select count(*)=1 from public.fh_medications where status='Confirmed'),'administrator manages medical records');
insert into test.ids values('member_invite',public.fh_invite((select id from test.ids where name='patient'),'member@example.invalid','family_member'));
insert into test.ids values('admin_invite',public.fh_invite((select id from test.ids where name='patient'),'admin2@example.invalid','administrator'));
insert into test.ids values('unverified_invite',public.fh_invite((select id from test.ids where name='patient'),'unverified@example.invalid','family_member'));
select test.denied($$select public.fh_invite((select id from test.ids where name='patient'),'outsider@example.invalid','administrator',now()+interval '8 days')$$,'maximum invitation lifetime');
select test.denied($$select public.fh_request_admin_removal((select id from test.ids where name='patient'),auth.uid(),'revoke')$$,'self removal/last administrator');

set request.jwt.claim.sub='00000000-0000-0000-0000-000000000004';
insert into test.ids values('other_patient',public.fh_create_demo_patient());
select test.ok((select count(*)=1 from public.fh_patients),'outsider sees only own patient');
select test.ok((select count(*)=0 from public.fh_doctors),'cross patient medical reads blocked');
select test.ok((select count(*)=0 from public.fh_invitations),'outsider cannot enumerate invitations');
select test.ok(not fh_private.upcoming((select id from test.ids where name='patient'),(select id from test.ids where name='appointment')),'helper does not leak appointment existence');
select test.denied($$select public.fh_accept_invitation((select id from test.ids where name='member_invite'))$$,'wrong recipient');
select test.denied($$insert into public.fh_doctors(patient_id,name) values((select id from test.ids where name='patient'),'Attack')$$,'cross patient insert');
select test.denied($$insert into public.fh_medications(patient_id,doctor_id,name) values((select id from test.ids where name='other_patient'),(select id from test.ids where name='doctor'),'Attack')$$,'cross patient relationship FK');
set request.jwt.claim.sub='00000000-0000-0000-0000-000000000005';
select test.denied($$select public.fh_accept_invitation((select id from test.ids where name='unverified_invite'))$$,'unverified email rejected');
set request.jwt.claim.sub='00000000-0000-0000-0000-000000000003';
select test.ok((select count(*)=1 from public.fh_invitations),'intended recipient can see own pending invitation');
select public.fh_accept_invitation((select id from test.ids where name='member_invite'));
select test.denied($$select public.fh_accept_invitation((select id from test.ids where name='member_invite'))$$,'invitation replay');
select test.ok((select count(*)=1 from public.fh_patients),'family member sees authorized patient only');
select test.ok((select count(*)=1 from public.fh_doctors),'family can read doctors');
select test.ok((select count(*)=0 from public.fh_audit_events),'family cannot read administrative audit trail');
select test.denied($$select public.fh_invite((select id from test.ids where name='patient'),'outsider@example.invalid','family_member')$$,'family cannot invite');
select test.denied($$select public.fh_promote_member((select id from test.ids where name='patient'),auth.uid())$$,'family cannot self elevate');
select test.denied($$insert into public.fh_doctors(patient_id,name) values((select id from test.ids where name='patient'),'Attack')$$,'family cannot create medical records');
update public.fh_doctors set name='Attack';
select test.ok((select count(*)=1 from public.fh_doctors where name='Fictional doctor'),'family updates affect zero rows under RLS');
delete from public.fh_medications;
select test.ok((select count(*)=1 from public.fh_medications),'family deletes affect zero rows under RLS');
select test.denied($$insert into public.fh_appointment_questions(patient_id,appointment_id,question) values((select id from test.ids where name='patient'),(select id from test.ids where name='past'),'Past')$$,'no questions on past appointments');
insert into public.fh_appointment_questions(patient_id,appointment_id,question) values((select id from test.ids where name='patient'),(select id from test.ids where name='appointment'),'Fictional family question') returning id as question_id \gset
insert into test.ids values('question',:'question_id');
update public.fh_appointment_questions set selected_for_checklist=true;
select test.ok((select count(*)=1 from public.fh_appointment_questions where selected_for_checklist and author_id=auth.uid()),'family question/checklist persistence and authenticated author');
select test.denied($$update public.fh_appointment_questions set author_id='00000000-0000-0000-0000-000000000001'$$,'author spoofing');
select test.denied($$update public.fh_appointment_questions set patient_id=(select id from test.ids where name='other_patient')$$,'cannot move question across patients');
select test.denied($$select public.fh_order_question((select id from test.ids where name='question'),5)$$,'family cannot organize question order');
set request.jwt.claim.sub='00000000-0000-0000-0000-000000000002';
select public.fh_accept_invitation((select id from test.ids where name='admin_invite'));
select test.ok((select count(*)=2 from public.fh_memberships where role='administrator'),'multiple administrators supported');
select test.ok((select count(*)=1 from public.fh_appointment_questions where selected_for_checklist),'another authorized member sees shared persisted checklist');
select public.fh_order_question((select id from test.ids where name='question'),5);
insert into test.ids values('remove_admin',public.fh_request_admin_removal((select id from test.ids where name='patient'),'00000000-0000-0000-0000-000000000001','demote'));
select test.ok((select role='administrator' from public.fh_memberships where user_id='00000000-0000-0000-0000-000000000001'),'request leaves target access unchanged');
select test.denied($$select public.fh_approve_admin_removal((select id from test.ids where name='remove_admin'))$$,'requester cannot approve for target');
select test.denied($$insert into public.fh_admin_removal_approvals(request_id,approved_by) values((select id from test.ids where name='remove_admin'),auth.uid())$$,'cannot forge approval');
set request.jwt.claim.sub='00000000-0000-0000-0000-000000000001';
select public.fh_approve_admin_removal((select id from test.ids where name='remove_admin'));
select test.ok((select role='family_member' from public.fh_memberships where user_id=auth.uid()),'explicit target approval demotes administrator');
select test.denied($$select public.fh_approve_admin_removal((select id from test.ids where name='remove_admin'))$$,'completed approval cannot replay');
set request.jwt.claim.sub='00000000-0000-0000-0000-000000000002';
select test.ok((select count(*)=1 from public.fh_admin_removal_approvals),'approval recorded');
select test.ok((select count(*)=3 from public.fh_audit_events where object_id=(select id from test.ids where name='remove_admin') and event in ('admin_removal_requested','admin_removal_approved','admin_removal_completed')),'request approval completion audited');
select public.fh_revoke_member((select id from test.ids where name='patient'),'00000000-0000-0000-0000-000000000003');
select test.denied($$select public.fh_revoke_member((select id from test.ids where name='patient'),auth.uid())$$,'cannot revoke last admin via family API');
select test.denied($$update public.fh_memberships set role='family_member' where user_id=auth.uid()$$,'last administrator direct demotion blocked');
set request.jwt.claim.sub='00000000-0000-0000-0000-000000000003';
select test.ok((select count(*)=0 from public.fh_patients),'revocation effective in existing authenticated session');
select test.ok((select count(*)=0 from public.fh_appointment_questions),'revoked question read blocked');
select test.denied($$insert into public.fh_appointment_questions(patient_id,appointment_id,question) values((select id from test.ids where name='patient'),(select id from test.ids where name='appointment'),'Attack')$$,'revoked question insert blocked');
update public.fh_appointment_questions set selected_for_checklist=false;
set request.jwt.claim.sub='00000000-0000-0000-0000-000000000002';
select test.ok((select selected_for_checklist from public.fh_appointment_questions where id=(select id from test.ids where name='question')),'revoked checklist write did not change data');
insert into test.ids values('expire_invite',public.fh_invite((select id from test.ids where name='patient'),'member@example.invalid','family_member'));
-- Test owner alone can advance invitation expiry; browser cannot edit it.
reset role;
update public.fh_invitations set expires_at=now()-interval '1 second' where id=(select id from test.ids where name='expire_invite');
set role authenticated;
set request.jwt.claim.sub='00000000-0000-0000-0000-000000000003';
select test.denied($$select public.fh_accept_invitation((select id from test.ids where name='expire_invite'))$$,'expired invitation');
select test.denied($$update public.fh_invitations set expires_at=now()+interval '1 day'$$,'cannot extend invitation directly');
set role anon;
set request.jwt.claim.sub='';
select test.denied($$select * from public.fh_patients$$,'anonymous has no patient list');
select test.denied($$select public.fh_create_demo_patient()$$,'anonymous bootstrap denied');
reset role;
select test.ok((select count(*)=11 from pg_class where relname like 'fh_%' and relkind='r' and relrowsecurity),'RLS enabled on every new table');
